export default behaviour({
  name: 'PauseKey',
  state: { paused: false },
  inputs: ['pressed'],
  outputs: ['pause', 'resume'],
  on: {
    pressed() { this.state.paused = !this.state.paused; this.emit(this.state.paused ? 'pause' : 'resume'); }
  }
});

