export default behaviour({
  name: 'PlayerHealth',
  state: { hp: 100, on: false },
  inputs: ['enter', 'exit'],
  outputs: ['hp', 'died'],
  on: {
    enter() { if (!this.state.on) { this.state.on = true; this.after(0.25, 'tick'); } },
    exit() { this.state.on = false; }
  },
  tick() {
    if (!this.state.on) return;
    this.state.hp = Math.max(0, this.state.hp - 5);
    if (!this.state.hp) { this.state.hp = 100; this.state.on = false; this.emit('died'); return; }
    this.after(0.25, 'tick');
  }
});

